AND (a.owner_id=#{${range}.userId} OR a.helper_id=#{${range}.userId}
    OR (
      (#{${range}.all}=TRUE OR c.owner_id=#{${range}.userId} OR o.dept_id IN #{dept})
      AND (#{${customerRange}.all}=TRUE OR c.owner_id=#{${customerRange}.userId} OR o.dept_id IN #{dept})
    ))

WHERE 1=1 
    AND (a.case_no LIKE CONCAT('%',#{query.keyword},'%') OR a.title LIKE CONCAT('%',#{query.keyword},'%') OR c.company_name LIKE CONCAT('%',#{query.keyword},'%') OR s.order_no LIKE CONCAT('%',#{query.keyword},'%'))
    AND a.status=#{query.status}
    AND a.issue_type=#{query.issueType}
    AND a.owner_id=#{query.ownerId}
    AND a.order_id IS NULL AND a.issue_type<>'CONSULTATION'
    AND a.status<>'CLOSED' AND a.next_follow_at<NOW()
    AND a.reported_at>=#{query.dateFrom}
    AND a.reported_at<DATE_ADD(#{query.dateTo},INTERVAL 1 DAY)
